import React, { useState, useEffect } from "react";
import { FaSearch } from "react-icons/fa";
import jsPDF from "jspdf";
import "jspdf-autotable";
import axios from "axios";
import { Link, useNavigate } from "react-router-dom"; // Import useNavigate
import { motion, AnimatePresence } from "framer-motion";
import "./SearchBar.css";

const AllOrders = () => {
  const [orders, setOrders] = useState([]);
  const [showAlert, setShowAlert] = useState(false);
  const [alertMessage, setAlertMessage] = useState("");
  const [showConfirmDialog, setShowConfirmDialog] = useState(false);
  const [confirmDialogData, setConfirmDialogData] = useState(null);
  const [searchQuery, setSearchQuery] = useState("");

  const navigate = useNavigate(); // Initialize useNavigate

  const fetchOrders = () => {
    axios
      .get("http://localhost:5555/orders/")
      .then((res) => {
        setOrders(Array.isArray(res.data.data) ? res.data.data : []);
      })
      .catch((err) => alert(err.message));
  };

  useEffect(() => {
    fetchOrders();
  }, []);

  const handleDeleteClick = (order) => {
    setConfirmDialogData(order);
    setShowConfirmDialog(true);
  };

  const handleDelete = () => {
    if (confirmDialogData) {
      axios
        .delete(`http://localhost:5555/orders/${confirmDialogData._id}`)
        .then(() => {
          setAlertMessage("Order deleted successfully!");
          setShowAlert(true);
          setTimeout(() => setShowAlert(false), 3000);
          setOrders(orders.filter((order) => order._id !== confirmDialogData._id));
        })
        .catch(() => {
          setAlertMessage("Error deleting order.");
          setShowAlert(true);
          setTimeout(() => setShowAlert(false), 3000);
        });
      setShowConfirmDialog(false);
    }
  };

  const handleCancel = () => {
    setShowConfirmDialog(false);
  };

  const filterOrders = orders.filter((order) =>
    order.orderId.toLowerCase().includes(searchQuery.toLowerCase())
  );

  const generateReport = () => {
    const doc = new jsPDF();
    doc.text("Order Management Report", 14, 16);

    const columns = [
      "firstName",
      "lastName",
      "email",
      "phoneNumber",
      "address",
      "city",
      "orderId",
      "specialInstructions",
      "pickupTime",
      "orderStatus",
    ];
    const rows = filterOrders.map((order) => [
      order.firstName,
      order.lastName,
      order.email,
      order.phoneNumber,
      order.address,
      order.city,
      order.orderId,
      order.specialInstructions,
      order.pickupTime,
      order.orderStatus,
    ]);

    doc.autoTable({
      head: [columns],
      body: rows,
      startY: 22,
    });

    doc.save("Orders_report.pdf");
  };

  const handleBackToHome = () => {
    navigate("/");
  };

  return (
    <div style={{ padding: "20px", backgroundColor: "#f3f4f6", minHeight: "100vh" }}>
      <h1 style={{ textAlign: "center", fontSize: "2.25rem", fontWeight: "bold", marginBottom: "1.5rem" }}>
        All Orders
      </h1>

      <div style={{ display: "flex", justifyContent: "center", marginBottom: "20px" }}>
        <SearchBar onSearch={(query) => setSearchQuery(query)} />
      </div>

      <table style={{ width: "100%", borderCollapse: "collapse", backgroundColor: "#fff" }}>
        <thead>
          <tr>
            <th>First Name</th>
            <th>Last Name</th>
            <th>Email</th>
            <th>Phone Number</th>
            <th>Address</th>
            <th>City</th>
            <th>Order Id</th>
            <th>Special Instructions</th>
            <th>Pickup Time</th>
            <th>Order Status</th>
            <th></th>
            <th></th>
          </tr>
        </thead>
        <tbody>
          {filterOrders.length > 0 ? (
            filterOrders.map((order) => (
              <tr key={order._id}>
                <td>{order.firstName}</td>
                <td>{order.lastName}</td>
                <td>{order.email}</td>
                <td>{order.phoneNumber}</td>
                <td>{order.address}</td>
                <td>{order.city}</td>
                <td>{order.orderId}</td>
                <td>{order.specialInstructions}</td>
                <td>{order.pickupTime}</td>
                <td>{order.orderStatus}</td>
                <td>
                  <Link to={`/update-order/${order._id}`} style={{ color: "#800000", textDecoration: "none" }}>
                    View Profile
                  </Link>
                </td>
                <td>
                  <button onClick={() => handleDeleteClick(order)} style={{ backgroundColor: "#dc2626", color: "#fff", padding: "8px 16px", borderRadius: "4px" }}>
                    Delete
                  </button>
                </td>
              </tr>
            ))
          ) : (
            <tr>
              <td colSpan="10">No orders available</td>
            </tr>
          )}
        </tbody>
      </table>

      <AnimatePresence>
        {showAlert && (
          <motion.div
            style={{ position: "fixed", top: "20px", right: "20px", backgroundColor: "#f87171", color: "#fff", padding: "16px", borderRadius: "4px" }}
            initial={{ opacity: 0, x: "100%" }}
            animate={{ opacity: 1, x: "0%" }}
            exit={{ opacity: 0, x: "100%" }}
          >
            {alertMessage}
          </motion.div>
        )}
      </AnimatePresence>

      {showConfirmDialog && (
        <div style={{ position: "fixed", top: 0, left: 0, right: 0, bottom: 0, backgroundColor: "rgba(0, 0, 0, 0.5)", display: "flex", justifyContent: "center", alignItems: "center" }}>
          <div style={{ backgroundColor: "#fff", padding: "24px", borderRadius: "8px", width: "90%", maxWidth: "400px" }}>
            <h2>Confirm Deletion</h2>
            <p>Are you sure you want to delete this order?</p>
            <div style={{ display: "flex", justifyContent: "flex-end" }}>
              <button onClick={handleDelete} style={{ backgroundColor: "#dc2626", color: "#fff", padding: "10px 20px", borderRadius: "4px", marginRight: "8px" }}>
                Yes, Delete
              </button>
              <button onClick={handleCancel} style={{ backgroundColor: "#e5e7eb", color: "#374151", padding: "10px 20px", borderRadius: "4px" }}>
                Cancel
              </button>
            </div>
          </div>
        </div>
      )}

      <div style={{ marginTop: "2rem", display: "flex", justifyContent: "center", flexDirection: "column", alignItems: "center" }}>
        <button onClick={generateReport} style={{ backgroundColor: "#1e40af", color: "#fff", padding: "10px 20px", borderRadius: "4px", marginBottom: "10px" }}>
          Generate Report
        </button>
        <button
          onClick={handleBackToHome}
          style={{
            backgroundColor: "#b30000",
            color: "white",
            padding: "10px 20px",
            border: "none",
            borderRadius: "5px",
            cursor: "pointer",
            fontSize: "16px",
            width: "auto",
          }}
        >
          Back to Home
        </button>
      </div>
    </div>
  );
};

const SearchBar = ({ onSearch }) => {
  const [searchQuery, setSearchQuery] = useState("");

  const handleSearch = (e) => {
    setSearchQuery(e.target.value);
    onSearch(e.target.value);
  };

  return <input type="text" placeholder="Search orders..." value={searchQuery} onChange={handleSearch} />;
};

export default AllOrders;
